style.css:
@-moz-document regexp(".*") {
/* Aplica Comic Sans en negrita a todo Internet respetando los íconos */
    *:not(i):not(.fa):not(.glyphicon):not([class*="icon"]):not([class*="Logo"]):not(svg):not(path) {
        font-family: "Comic Sans MS", "Comic Sans", cursive, sans-serif !important;
        font-weight: bold !important;
    }
}
